using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.Extensions.Logging;
using ModelContextProtocol.Server;

namespace McpStdioServer;

[McpServerToolType]
public sealed class ApiTools
{
    [McpServerTool, Description("Fetches data from an external API endpoint and returns the JSON response.")]
    public static async Task<string> FetchApi(
        HttpClient httpClient,
        ILogger<ApiTools> logger,
        [Description("The full URL of the API endpoint to call.")] string url,
        CancellationToken cancellationToken)
    {
        logger.LogInformation("Calling external API: {Url}", url);

        using var response = await httpClient.GetAsync(url, cancellationToken);
        response.EnsureSuccessStatusCode();

        var json = await response.Content.ReadFromJsonAsync<JsonElement>(cancellationToken);
        var result = JsonSerializer.Serialize(json, new JsonSerializerOptions { WriteIndented = true });

        logger.LogInformation("API call succeeded ({StatusCode})", (int)response.StatusCode);
        return result;
    }
}

using System.ComponentModel;
using ModelContextProtocol.Server;

namespace McpStdioServer;

[McpServerPromptType]
public sealed class SummarizePrompt
{
    [McpServerPrompt, Description("Generates a prompt that asks the model to summarize the provided text.")]
    public static IList<Microsoft.Extensions.AI.ChatMessage> Summarize(
        [Description("The text content to summarize.")] string text,
        [Description("Maximum number of sentences in the summary (default: 3).")] int maxSentences = 3)
    {
        return
        [
            new(Microsoft.Extensions.AI.ChatRole.User,
                $"Summarize the following text in at most {maxSentences} sentence(s). " +
                $"Be concise and capture the key points.\n\n{text}")
        ];
    }
}

